#!/usr/bin/env python3
"""Build the Oscar Scores Trend Analysis HTML report."""

import csv
import json
from collections import Counter, defaultdict
from pathlib import Path

# ── Load data ────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            "year": int(r["Year"]),
            "film": r["Film"],
            "composer": r["Composer"],
        })

# ── Helper: split combined composers ─────────────────────────────────
def split_composers(composer_str):
    """Split a combined composer string into individual names."""
    return [c.strip() for c in composer_str.split(",")]

# Build expanded list (one row per individual composer per year)
expanded = []
for r in rows:
    for c in split_composers(r["composer"]):
        expanded.append({"year": r["year"], "film": r["film"], "composer": c})

# ── KPI 1: Total Unique Composers ────────────────────────────────────
unique_composers = sorted(set(e["composer"] for e in expanded))
kpi_total_unique = len(unique_composers)

# ── KPI 2: Maximum Wins by a Single Composer ─────────────────────────
composer_win_counts = Counter(e["composer"] for e in expanded)
kpi_max_wins = max(composer_win_counts.values())
top_composers = composer_win_counts.most_common()

# ── KPI 3: Repeat Winner Rate ────────────────────────────────────────
seen_composers = set()
repeat_years = 0
for r in rows:
    composers = split_composers(r["composer"])
    if any(c in seen_composers for c in composers):
        repeat_years += 1
    seen_composers.update(composers)
kpi_repeat_rate = round(repeat_years / len(rows) * 100, 1)

# ── KPI 4: Decade with Most Unique Winners ───────────────────────────
def get_decade(year):
    return f"{(year // 10) * 10}s"

decade_composers = defaultdict(set)
for e in expanded:
    decade_composers[get_decade(e["year"])].add(e["composer"])

decade_unique_counts = {d: len(c) for d, c in decade_composers.items()}
kpi_best_decade = max(decade_unique_counts, key=decade_unique_counts.get)
kpi_best_decade_count = decade_unique_counts[kpi_best_decade]

# ── Decade breakdown ─────────────────────────────────────────────────
decades_order = ["1930s", "1940s", "1950s", "1960s", "1970s", "1980s", "1990s", "2000s", "2010s", "2020s"]
decade_stats = {}
for d in decades_order:
    yrs = [e["year"] for e in expanded if get_decade(e["year"]) == d]
    total_ceremonies = len(set(yrs))
    composers_in_decade = decade_composers.get(d, set())
    unique_count = len(composers_in_decade)
    # repeat winners in this decade
    decade_comp_wins = Counter(e["composer"] for e in expanded if get_decade(e["year"]) == d)
    repeat_count = sum(1 for c, w in decade_comp_wins.items() if w > 1)
    decade_stats[d] = {
        "ceremonies": total_ceremonies,
        "unique_winners": unique_count,
        "repeat_winners": repeat_count,
        "top_composer": decade_comp_wins.most_common(1)[0] if decade_comp_wins else ("N/A", 0),
    }

# ── Era analysis ─────────────────────────────────────────────────────
eras = {
    "Golden Age (1934–1959)": (1934, 1959),
    "Silver Age (1960–1979)": (1960, 1979),
    "Modern Era (1980–1999)": (1980, 1999),
    "Contemporary Era (2000–2026)": (2000, 2026),
}

era_stats = {}
for era_name, (start, end) in eras.items():
    era_entries = [e for e in expanded if start <= e["year"] <= end]
    era_rows_set = [r for r in rows if start <= r["year"] <= end]
    era_comp_wins = Counter(e["composer"] for e in era_entries)
    era_stats[era_name] = {
        "ceremonies": len(era_rows_set),
        "unique_composers": len(set(e["composer"] for e in era_entries)),
        "top3": era_comp_wins.most_common(3),
        "repeat_rate": round(
            sum(1 for c, w in era_comp_wins.items() if w > 1) / len(set(e["composer"] for e in era_entries)) * 100, 1
        ) if era_entries else 0,
    }

# ── Top composers for bar chart ───────────────────────────────────────
top15 = top_composers[:15]

# ── Decade chart data ─────────────────────────────────────────────────
decade_chart_labels = []
decade_chart_unique = []
decade_chart_repeat = []
for d in decades_order:
    if d in decade_stats and decade_stats[d]["ceremonies"] > 0:
        decade_chart_labels.append(d)
        ds = decade_stats[d]
        decade_chart_unique.append(ds["unique_winners"])
        decade_chart_repeat.append(ds["repeat_winners"])

# ── Notable milestones ───────────────────────────────────────────────
# First winner
first_winner = rows[0]

# Most recent winner
last_winner = rows[-1]

# Longest gap between wins for a single composer
composer_years = defaultdict(list)
for e in expanded:
    composer_years[e["composer"]].append(e["year"])

longest_gap_composer = None
longest_gap_years = 0
longest_gap_detail = ""
for comp, years in composer_years.items():
    if len(years) >= 2:
        years_sorted = sorted(years)
        for i in range(len(years_sorted) - 1):
            gap = years_sorted[i+1] - years_sorted[i]
            if gap > longest_gap_years:
                longest_gap_years = gap
                longest_gap_composer = comp
                longest_gap_detail = f"{years_sorted[i]} to {years_sorted[i+1]}"

# Consecutive wins (streaks)
streaks = []
current_comp = None
current_streak = 0
current_start = None
for r in rows:
    composers = split_composers(r["composer"])
    # Check if any composer from this win continues from previous
    if current_comp and any(c in current_comp for c in composers):
        current_streak += 1
    else:
        if current_streak >= 2:
            streaks.append((current_comp_str, current_streak, current_start, rows[rows.index(r)-1]["year"]))
        current_comp = set(composers)
        current_comp_str = r["composer"]
        current_streak = 1
        current_start = r["year"]
# Final streak
if current_streak >= 2:
    streaks.append((current_comp_str, current_streak, current_start, rows[-1]["year"]))

# Composers who waited longest between first credited appearance and first win
# (we only have winning years, so we can't compute this)
# Instead: number of first-time winners by decade
first_time_by_decade = defaultdict(int)
seen = set()
for r in rows:
    d = get_decade(r["year"])
    composers = split_composers(r["composer"])
    new = [c for c in composers if c not in seen]
    if new:
        first_time_by_decade[d] += len(new)
    seen.update(composers)

# ── Build HTML ────────────────────────────────────────────────────────

def js_json(obj):
    return json.dumps(obj)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --primary: #1a1a2e;
    --accent: #c9a84c;
    --accent2: #8b6914;
    --bg: #faf8f4;
    --card-bg: #ffffff;
    --text: #2d2d2d;
    --text-light: #5a5a5a;
    --border: #e0d9ce;
    --kpi-bg: linear-gradient(135deg, #1a1a2e 0%, #2d2d4e 100%);
    --golden: #c9a84c;
    --silver: #7b8b9e;
    --modern: #4a7c96;
    --contemp: #2e8b6e;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Georgia', 'Times New Roman', serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.7;
  }}

  /* ── Hero ── */
  .hero {{
    background: linear-gradient(135deg, #0d0d1a 0%, #1a1a2e 40%, #2d2d1a 100%);
    color: #f0e6c8;
    padding: 60px 40px 50px;
    text-align: center;
    border-bottom: 3px solid var(--accent);
  }}
  .hero h1 {{
    font-size: 2.6em;
    font-weight: normal;
    letter-spacing: 0.03em;
    margin-bottom: 10px;
    color: #f5e7c6;
  }}
  .hero .subtitle {{
    font-size: 1.15em;
    color: #c9a84c;
    font-style: italic;
    margin-bottom: 8px;
  }}
  .hero .meta {{
    font-size: 0.9em;
    color: #8a8a7a;
    margin-top: 15px;
  }}

  /* ── KPI Cards ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    max-width: 1100px;
    margin: -30px auto 40px;
    padding: 0 30px;
    position: relative;
    z-index: 2;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 8px;
    padding: 24px 20px;
    text-align: center;
    box-shadow: 0 2px 12px rgba(0,0,0,0.08);
    border-top: 3px solid var(--accent);
  }}
  .kpi-card .kpi-value {{
    font-size: 2.4em;
    font-weight: bold;
    color: var(--primary);
    line-height: 1.2;
  }}
  .kpi-card .kpi-label {{
    font-size: 0.85em;
    color: var(--text-light);
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }}
  .kpi-card .kpi-detail {{
    font-size: 0.8em;
    color: #999;
    margin-top: 4px;
  }}

  /* ── Content ── */
  .container {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 30px 60px;
  }}
  section {{
    margin-bottom: 50px;
  }}
  h2 {{
    font-size: 1.7em;
    color: var(--primary);
    border-bottom: 2px solid var(--accent);
    padding-bottom: 8px;
    margin-bottom: 20px;
    font-weight: normal;
    letter-spacing: 0.02em;
  }}
  h3 {{
    font-size: 1.2em;
    color: #3a3a4e;
    margin: 24px 0 10px;
    font-weight: normal;
  }}
  p {{
    margin-bottom: 14px;
    color: var(--text);
  }}
  .lead {{
    font-size: 1.1em;
    color: var(--text-light);
    font-style: italic;
  }}

  /* ── Charts ── */
  .chart-box {{
    background: var(--card-bg);
    border-radius: 8px;
    padding: 25px;
    margin: 20px 0;
    box-shadow: 0 1px 8px rgba(0,0,0,0.06);
  }}
  .chart-box canvas {{
    max-width: 100%;
  }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }}

  /* ── Tables ── */
  .table-wrap {{
    overflow-x: auto;
    margin: 20px 0;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.95em;
  }}
  thead th {{
    background: var(--primary);
    color: #f0e6c8;
    padding: 10px 12px;
    text-align: left;
    font-weight: normal;
    letter-spacing: 0.03em;
    font-size: 0.85em;
    text-transform: uppercase;
  }}
  tbody td {{
    padding: 10px 12px;
    border-bottom: 1px solid var(--border);
  }}
  tbody tr:nth-child(even) {{
    background: #f9f7f2;
  }}
  tbody tr:hover {{
    background: #f0ece0;
  }}
  .num {{ text-align: right; font-variant-numeric: tabular-nums; }}
  .highlight-row {{ background: #fdf8e8 !important; }}

  /* ── Era Tags ── */
  .era-tag {{
    display: inline-block;
    padding: 2px 10px;
    border-radius: 3px;
    font-size: 0.78em;
    font-weight: bold;
    letter-spacing: 0.04em;
    margin-right: 6px;
  }}
  .era-golden {{ background: #fdf3d0; color: #8b6914; }}
  .era-silver {{ background: #e8edf2; color: #3d5368; }}
  .era-modern {{ background: #dceaf0; color: #2d5a6e; }}
  .era-contemp {{ background: #d8f0e8; color: #1e6b4e; }}

  /* ── Milestones ── */
  .milestone-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin: 20px 0;
  }}
  .milestone {{
    background: var(--card-bg);
    border-radius: 6px;
    padding: 18px 20px;
    border-left: 4px solid var(--accent);
    box-shadow: 0 1px 6px rgba(0,0,0,0.05);
  }}
  .milestone .m-year {{
    font-size: 0.82em;
    color: var(--accent2);
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 4px;
  }}
  .milestone .m-title {{
    font-weight: bold;
    font-size: 1.05em;
  }}

  /* ── Footer ── */
  footer {{
    text-align: center;
    padding: 30px;
    color: #aaa;
    font-size: 0.82em;
    border-top: 1px solid var(--border);
  }}

  /* ── Responsive ── */
  @media (max-width: 768px) {{
    .kpi-grid {{ grid-template-columns: 1fr 1fr; }}
    .chart-row {{ grid-template-columns: 1fr; }}
    .milestone-grid {{ grid-template-columns: 1fr; }}
    .hero h1 {{ font-size: 1.6em; }}
  }}
</style>
</head>
<body>

<!-- ═══════════ HERO ═══════════ -->
<header class="hero">
  <h1>Nine Decades of Oscar-Winning Scores</h1>
  <p class="subtitle">A Historical Trend Analysis of the Academy Award for Best Original Score</p>
  <p class="meta">93 Ceremonies &middot; 1934–2026 &middot; {kpi_total_unique} Unique Composers</p>
</header>

<!-- ═══════════ KPI CARDS ═══════════ -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-value">{kpi_total_unique}</div>
    <div class="kpi-label">Total Unique Composers</div>
    <div class="kpi-detail">Across all 93 ceremonies</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{kpi_max_wins}</div>
    <div class="kpi-label">Maximum Wins</div>
    <div class="kpi-detail">By a single composer</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{kpi_repeat_rate}%</div>
    <div class="kpi-label">Repeat Winner Rate</div>
    <div class="kpi-detail">{repeat_years} of {len(rows)} ceremonies</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{kpi_best_decade}</div>
    <div class="kpi-label">Most Diverse Decade</div>
    <div class="kpi-detail">{kpi_best_decade_count} unique winners</div>
  </div>
</div>

<div class="container">

<!-- ═══════════ SECTION 1: OVERVIEW ═══════════ -->
<section id="overview">
  <h2>1. Dataset Overview &amp; Historical Context</h2>
  <p class="lead">
    The Academy Award for Best Original Score has been awarded at 93 ceremonies spanning from the 6th Academy Awards
    in 1934 through the 98th ceremony in March 2026. This dataset consolidates every winner into a single canonical record,
    tracing the evolution of film music's highest honor across nine decades.
  </p>
  <p>
    The award category has undergone several name changes and structural shifts across its history. In certain years, the Academy
    split the category into separate awards for dramatic scores and comedy/musical scores; this dataset presents one
    consolidated winner per ceremony year. The 93 winning scores represent <strong>{kpi_total_unique} distinct composers</strong>
    (counting individuals within shared awards) and <strong>{len(set(r['film'] for r in rows))} unique films</strong>.
  </p>
  <p>
    The composer pool reveals a striking concentration: <strong>{kpi_repeat_rate}%</strong> of all ceremonies were won by a composer
    who had already claimed the award at least once before. A handful of names appear again and again across the decades,
    while many composers appear just once — a testament to both the towering dominance of certain figures and the category's
    capacity to recognize new voices.
  </p>
  <p>
    The data spans from the Golden Age of Hollywood studio orchestras through the synthesizer experiments of the 1980s,
    the orchestral renaissance of the 1990s and 2000s, and into today's eclectic landscape where traditional orchestral
    writing coexists with electronic, experimental, and globally influenced scores.
  </p>
</section>

<!-- ═══════════ SECTION 2: TOP COMPOSERS ═══════════ -->
<section id="top-composers">
  <h2>2. Most Awarded Composers</h2>
  <p>
    A small cadre of composers has dominated the Best Original Score category. The top-ranked composer —
    <strong>{top15[0][0]}</strong> — has won an extraordinary <strong>{top15[0][1]} times</strong>, a figure that
    underscores a career of remarkable longevity and critical recognition. The table below ranks every composer who has
    won more than once, along with the complete leaderboard chart.
  </p>

  <div class="chart-box">
    <canvas id="topComposersChart" height="400"></canvas>
  </div>

  <div class="table-wrap">
    <table>
      <thead>
        <tr>
          <th>Rank</th>
          <th>Composer</th>
          <th>Wins</th>
          <th>Winning Span</th>
          <th>Era(s)</th>
        </tr>
      </thead>
      <tbody>
"""

# Build top composers table
for rank, (composer, wins) in enumerate(top_composers, 1):
    years = sorted(composer_years[composer])
    span = f"{years[0]}–{years[-1]}" if len(years) > 1 else str(years[0])
    # Determine era tags
