#!/usr/bin/env python3
"""Build the Oscar Scores Trend Analysis HTML report."""

import csv
import json
from collections import Counter, defaultdict
from pathlib import Path

# ── Load data ────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            "year": int(r["Year"]),
            "film": r["Film"],
            "composer": r["Composer"],
        })

# ── Helper: split combined composers ─────────────────────────────────
def split_composers(composer_str):
    """Split a combined composer string into individual names."""
    return [c.strip() for c in composer_str.split(",")]

# Build expanded list (one row per individual composer per year)
expanded = []
for r in rows:
    for c in split_composers(r["composer"]):
        expanded.append({"year": r["year"], "film": r["film"], "composer": c})

# ── KPI 1: Total Unique Composers ────────────────────────────────────
unique_composers = sorted(set(e["composer"] for e in expanded))
kpi_total_unique = len(unique_composers)

# ── KPI 2: Maximum Wins by a Single Composer ─────────────────────────
composer_win_counts = Counter(e["composer"] for e in expanded)
kpi_max_wins = max(composer_win_counts.values())
top_composers = composer_win_counts.most_common()

# ── KPI 3: Repeat Winner Rate ────────────────────────────────────────
seen_composers = set()
repeat_years = 0
for r in rows:
    composers = split_composers(r["composer"])
    if any(c in seen_composers for c in composers):
        repeat_years += 1
    seen_composers.update(composers)
kpi_repeat_rate = round(repeat_years / len(rows) * 100, 1)

# ── KPI 4: Decade with Most Unique Winners ───────────────────────────
def get_decade(year):
    return f"{(year // 10) * 10}s"

decade_composers = defaultdict(set)
for e in expanded:
    decade_composers[get_decade(e["year"])].add(e["composer"])

decade_unique_counts = {d: len(c) for d, c in decade_composers.items()}
kpi_best_decade = max(decade_unique_counts, key=decade_unique_counts.get)
kpi_best_decade_count = decade_unique_counts[kpi_best_decade]

# ── Decade breakdown ─────────────────────────────────────────────────
decades_order = ["1930s", "1940s", "1950s", "1960s", "1970s", "1980s", "1990s", "2000s", "2010s", "2020s"]
decade_stats = {}
for d in decades_order:
    yrs = [e["year"] for e in expanded if get_decade(e["year"]) == d]
    total_ceremonies = len(set(yrs))
    composers_in_decade = decade_composers.get(d, set())
    unique_count = len(composers_in_decade)
    # repeat winners in this decade
    decade_comp_wins = Counter(e["composer"] for e in expanded if get_decade(e["year"]) == d)
    repeat_count = sum(1 for c, w in decade_comp_wins.items() if w > 1)
    decade_stats[d] = {
        "ceremonies": total_ceremonies,
        "unique_winners": unique_count,
        "repeat_winners": repeat_count,
        "top_composer": decade_comp_wins.most_common(1)[0] if decade_comp_wins else ("N/A", 0),
    }

# ── Era analysis ─────────────────────────────────────────────────────
eras = {
    "Golden Age (1934–1959)": (1934, 1959),
    "Silver Age (1960–1979)": (1960, 1979),
    "Modern Era (1980–1999)": (1980, 1999),
    "Contemporary Era (2000–2026)": (2000, 2026),
}

era_stats = {}
for era_name, (start, end) in eras.items():
    era_entries = [e for e in expanded if start <= e["year"] <= end]
    era_rows_set = [r for r in rows if start <= r["year"] <= end]
    era_comp_wins = Counter(e["composer"] for e in era_entries)
    era_stats[era_name] = {
        "ceremonies": len(era_rows_set),
        "unique_composers": len(set(e["composer"] for e in era_entries)),
        "top3": era_comp_wins.most_common(3),
        "repeat_rate": round(
            sum(1 for c, w in era_comp_wins.items() if w > 1) / len(set(e["composer"] for e in era_entries)) * 100, 1
        ) if era_entries else 0,
    }

# ── Top composers for bar chart ───────────────────────────────────────
top15 = top_composers[:15]

# ── Decade chart data ─────────────────────────────────────────────────
decade_chart_labels = []
decade_chart_unique = []
decade_chart_repeat = []
for d in decades_order:
    if d in decade_stats and decade_stats[d]["ceremonies"] > 0:
        decade_chart_labels.append(d)
        ds = decade_stats[d]
        decade_chart_unique.append(ds["unique_winners"])
        decade_chart_repeat.append(ds["repeat_winners"])

# ── Notable milestones ───────────────────────────────────────────────
# First winner
first_winner = rows[0]

# Most recent winner
last_winner = rows[-1]

# Longest gap between wins for a single composer
composer_years = defaultdict(list)
for e in expanded:
    composer_years[e["composer"]].append(e["year"])

longest_gap_composer = None
longest_gap_years = 0
longest_gap_detail = ""
for comp, years in composer_years.items():
    if len(years) >= 2:
        years_sorted = sorted(years)
        for i in range(len(years_sorted) - 1):
            gap = years_sorted[i+1] - years_sorted[i]
            if gap > longest_gap_years:
                longest_gap_years = gap
                longest_gap_composer = comp
                longest_gap_detail = f"{years_sorted[i]} to {years_sorted[i+1]}"

# Consecutive wins (streaks)
streaks = []
current_comp = None
current_streak = 0
current_start = None
for r in rows:
    composers = split_composers(r["composer"])
    # Check if any composer from this win continues from previous
    if current_comp and any(c in current_comp for c in composers):
        current_streak += 1
    else:
        if current_streak >= 2:
            streaks.append((current_comp_str, current_streak, current_start, rows[rows.index(r)-1]["year"]))
        current_comp = set(composers)
        current_comp_str = r["composer"]
        current_streak = 1
        current_start = r["year"]
# Final streak
if current_streak >= 2:
    streaks.append((current_comp_str, current_streak, current_start, rows[-1]["year"]))

# Composers who waited longest between first credited appearance and first win
# (we only have winning years, so we can't compute this)
# Instead: number of first-time winners by decade
first_time_by_decade = defaultdict(int)
seen = set()
for r in rows:
    d = get_decade(r["year"])
    composers = split_composers(r["composer"])
    new = [c for c in composers if c not in seen]
    if new:
        first_time_by_decade[d] += len(new)
    seen.update(composers)

# ── Build HTML ────────────────────────────────────────────────────────

def js_json(obj):
    return json.dumps(obj)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
