    color: #f5e7c6;
  }}
  .hero .subtitle {{
    font-size: 1.15em;
    color: #c9a84c;
    font-style: italic;
    margin-bottom: 8px;
  }}
  .hero .meta {{
    font-size: 0.9em;
    color: #8a8a7a;
    margin-top: 15px;
  }}

  /* ── KPI Cards ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
