   return f\"{(year // 10) * 10}s\"\n\ndecade_composers = defaultdict(set)\nfor e in expanded:\n    decade_composers[get_decade(e[\"year\"])].add(e[\"composer\"])\n\ndecade_unique_counts = {d: len(c) for d, c in decade_composers.items()}\nkpi_best_decade = max(decade_unique_counts, key=decade_unique_counts.get)\nkpi_best_decade_count = decade_unique_counts[kpi_best_decade]\n\n# ── Decade breakdown ─────────────────────────────────────────────────\ndecades_order = [\"1930s\", \"1940s\", \"1950s\", \"1960s\", \"1970s\", \"1980s\", \"1990s\", \"2000s\", \"2010s\", \"2020s\"]\ndecade_stats = {}\nfor d in decades_order:\n    yrs = [e[\"year\"] for e in expanded if get_decade(e[\"year\"]) == d]\n    total_ceremonies = len(set(yrs))\n    composers_in_decade = decade_composers.get(d, set())\n    unique_count = len(composers_in_decade)\n    # repeat winners in this decade\n    decade_comp_wins = Counter(e[\"composer\"] for e in expanded if get_decade(e[\"year\"]) == d)\n    repeat_count = sum(1 for c, w in decade_comp_wins.items() if w > 1)\n    decade_stats[d] = {\n        \"ceremonies\": total_ceremonies,\n        \"unique_winners\": unique_count,\n        \"repeat_winners\": repeat_count,\n        \"top_composer\": decade_comp_wins.most_common(1)[0] if decade_comp_wins else (\"N/A\", 0),\n    }\n\n# ── Era analysis ─────────────────────────────────────────────────────\neras = {\n    \"Golden Age (1934–1959)\": (1934, 1959),\n    \"Silver Age (1960–1979)\": (1960, 1979),\n    \"Modern Era (1980–1999)\": (1980, 1999),\n    \"Contemporary Era (2000–2026)\": (2000, 2026),\n}\n\nera_stats = {}\nfor era_name, (start, end) in eras.items():\n    era_entries = [e for e in expanded if start <= e[\"year\"] <= end]\n    era_rows_set = [r for r in rows if start <= r[\"year\"] <= end]\n    era_comp_wins = Counter(e[\"composer\"] for e in era_entries)\n    era_stats[era_name] = {\n        \"ceremonies\": len(era_rows_set),\n        \"unique_composers\": len(set(e[\"composer\"] for e in era_entries)),\n        \"top3\": era_comp_wins.most_common(3),\n        \"repeat_rate\": round(\n            sum(1 for c, w in era_comp_wins.items() if w > 1) / len(set(e[\"composer\"] for e in era_entries)) * 100, 1\n        ) if era_entries else 0,\n    }\n\n# ── Top composers for bar chart ───────────────────────────────────────\ntop15 = top_composers[:15]\n\n# ── Decade chart data ─────────────────────────────────────────────────\ndecade_chart_labels = []\ndecade_chart_unique = []\ndecade_chart_repeat = []\nfor d in decades_order:\n    if d in decade_stats and decade_stats[d][\"ceremonies\"] > 0:\n        decade_chart_labels.append(d)\n        ds = decade_stats[d]\n        decade_chart_unique.append(ds[\"unique_winners\"])\n        decade_chart_repeat.append(ds[\"repeat_winners\"])\n\n# ── Notable milestones ───────────────────────────────────────────────\n# First winner\nfirst_winner = rows[0]\n\n# Most recent winner\nlast_winner = rows[-1]\n\n# Longest gap between wins for a single composer\ncomposer_years = defaultdict(list)\nfor e in expanded:\n    composer_years[e[\"composer\"]].append(e[\"year\"])\n\nlongest_gap_composer = None\nlongest_gap_years = 0\nlongest_gap_detail = \"\"\nfor comp, years in composer_years.items():\n    if len(years) >= 2:\n        years_sorted = sorted(years)\n        for i in range(len(years_sorted) - 1):\n            gap = years_sorted[i+1] - years_sorted[i]\n            if gap > longest_gap_years:\n                longest_gap_years = gap\n                longest_gap_composer = comp\n                longest_gap_detail = f\"{years_sorted[i]} to {years_sorted[i+1]}\"\n\n# Consecutive wins (streaks)\nstreaks = []\ncurrent_comp = None\ncurrent_streak = 0\ncurrent_start = None\nfor r in rows:\n    composers = split_composers(r[\"composer\"])\n    # Check if any composer from this win continues from previous\n    if current_comp and any(c in current_comp for c in composers):\n        current_streak += 1\n    else:\n        if current_streak >= 2:\n            streaks.append((current_comp_str, current_streak, current_start, rows[rows.index(r)-1][\"year\"]))\n        current_comp = set(composers)\n        current_comp_str = r[\"composer\"]\n        current_streak = 1\n        current_start = r[\"year\"]\n# Final streak\nif current_streak >= 2:\n    streaks.append((current_comp_str, current_streak, current_start, rows[-1][\"year\"]))\n\n# Composers who waited longest between first credited appearance and first win\n# (we only have winning years, so we can't compute this)\n# Instead: number of first-time winners by decade\nfirst_time_by_decade = defaultdict(int)\nseen = set()\nfor r in rows:\n    d = get_decade(r[\"year\"])\n    composers = split_composers(r[\"composer\"])\n    new = [c for c in composers if c not in seen]\n    if new:\n        first_time_by_decade[d] += len(new)\n    seen.update(composers)\n\n# ── Build HTML ────────────────────────────────────────────────────────\n\ndef js_json(obj):\n    return json.dumps(obj)\n\nhtml = f\"\"\"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Nine Decades of Oscar-Winning Scores (1934–2026)</title>\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js\"></script>\n<style>\n  :root {{\n    --primary: #1a1a2e;\n    --accent: #c9a84c;\n    --accent2: #8b6914;\n    --bg: #faf8f4;\n    --card-bg: #ffffff;\n    --text: #2d2d2d;\n    --text-light: #5a5a5a;\n    --border: #e0d9ce;\n    --kpi-bg: linear-gradient(135deg, #1a1a2e 0%, #2d2d4e 100%);\n    --golden: #c9a84c;\n    --silver: #7b8b9e;\n    --modern: #4a7c96;\n    --contemp: #2e8b6e;\n  }}\n  * {{ margin: 0; padding: 0; box-sizing: border-box; }}\n  body {{\n    font-family: 'Georgia', 'Times New Roman', serif;\n    background: var(--bg);\n    color: var(--text);\n    line-height: 1.7;\n  }}\n\n  /* ── Hero ── */\n  .hero {{\n    background: linear-gradient(135deg, #0d0d1a 0%, #1a1a2e 40%, #2d2d1a 100%);\n    color: #f0e6c8;\n    padding: 60px 40px 50px;\n    text-align: center;\n    border-bottom: 3px solid var(--accent);\n  }}\n  .hero h1 {{\n    font-size: 2.6em;\n    font-weight: normal;\n    letter-spacing: 0.03em;\n    margin-bottom: 10px;\n    color: #f5e7c6;\n  }}\n  .hero .subtitle {{\n    font-size: 1.15em;\n    color: #c9a84c;\n    font-style: italic;\n    margin-bottom: 8px;\n  }}\n  .hero .meta {{\n    font-size: 0.9em;\n    color: #8a8a7a;\n    margin-top: 15px;\n  }}\n\n  /* ── KPI Cards ── */\n  .kpi-grid {{\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 20px;\n    max-width: 1100px;\n    margin: -30px auto 40px;\n    padding: 0 30px;\n    position: relative;\n    z-index: 2;\n  }}\n  .kpi-card {{\n    background: var(--card-bg);\n    border-radius: 8px;\n    padding: 24px 20px;\n    text-align: center;\n    box-shadow: 0 2px 12px rgba(0,0,0,0.08);\n    border-top: 3px solid var(--accent);\n  }}\n  .kpi-card .kpi-value {{\n    font-size: 2.4em;\n    font-weight: bold;\n    color: var(--primary);\n    line-height: 1.2;\n  }}\n  .kpi-card .kpi-label {{\n    font-size: 0.85em;\n    color: var(--text-light);\n    margin-top: 6px;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n  }}\n  .kpi-card .kpi-detail {{\n    font-size: 0.8em;\n    color: #999;\n    margin-top: 4px;\n  }}\n\n  /* ── Content ── */\n  .container {{\n    max-width: 1100px;\n    margin: 0 auto;\n    padding: 0 30px 60px;\n  }}\n  section {{\n    margin-bottom: 50px;\n  }}\n  h2 {{\n    font-size: 1.7em;\n    color: var(--primary);\n    border-bottom: 2px solid var(--accent);\n    padding-bottom: 8px;\n    margin-bottom: 20px;\n    font-weight: normal;\n    letter-spacing: 0.02em;\n  }}\n  h3 {{\n    font-size: 1.2em;\n    color: #3a3a4e;\n    margin: 24px 0 10px;\n    font-weight: normal;\n  }}\n  p {{\n    margin-bottom: 14px;\n    color: var(--text);\n  }}\n  .lead {{\n    font-size: 1.1em;\n    color: var(--text-light);\n    font-style: italic;\n  }}\n\n  /* ── Charts ── */\n  .chart-box {{\n    background: var(--card-bg);\n    border-radius: 8px;\n    padding: 25px;\n    margin: 20px 0;\n    box-shadow: 0 1px 8px rgba(0,0,0,0.06);\n  }}\n  .chart-box canvas {{\n    max-width: 100%;\n  }}\n  .chart-row {{\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 20px;\n  }}\n\n  /* ── Tables ── */\n  .table-wrap {{\n    overflow-x: auto;\n    margin: 20px 0;\n  }}\n  table {{\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 0.95em;\n  }}\n  thead th {{\n    background: var(--primary);\n    color: #f0e6c8;\n    padding: 10px 12px;\n    text-align: left;\n    font-weight: normal;\n    letter-spacing: 0.03em;\n    font-size: 0.85em;\n    text-transform: uppercase;\n  }}\n  tbody td {{\n    padding: 10px 12px;\n    border-bottom: 1px solid var(--border);\n  }}\n  tbody tr:nth-child(even) {{\n    background: #f9f7f2;\n  }}\n  tbody tr:hover {{\n    background: #f0ece0;\n  }}\n  .num {{ text-align: right; font-variant-numeric: tabular-nums; }}\n  .highlight-row {{ background: #fdf8e8 !important; }}\n\n  /* ── Era Tags ── */\n  .era-tag {{\n    display: inline-block;\n    padding: 2px 10px;\n    border-radius: 3px;\n    font-size: 0.78em;\n    font-weight: bold;\n    letter-spacing: 0.04em;\n    margin-right: 6px;\n  }}\n  .era-golden {{ background: #fdf3d0; color: #8b6914; }}\n  .era-silver {{ background: #e8edf2; color: #3d5368; }}\n  .era-modern {{ background: #dceaf0; color: #2d5a6e; }}\n  .era-contemp {{ background: #d8f0e8; color: #1e6b4e; }}\n\n  /* ── Milestones ── */\n  .milestone-grid {{\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    margin: 20px 0;\n  }}\n  .milestone {{\n    background: var(--card-bg);\n    border-radius: 6px;\n    padding: 18px 20px;\n    border-left: 4px solid var(--accent);\n    box-shadow: 0 1px 6px rgba(0,0,0,0.05);\n  }}\n  .milestone .m-year {{\n    font-size: 0.82em;\n    color: var(--accent2);\n    text-transform: uppercase;\n    letter-spacing: 0.06em;\n    margin-bottom: 4px;\n  }}\n  .milestone .m-title {{\n    font-weight: bold;\n    font-size: 1.05em;\n  }}\n\n  /* ── Footer ── */\n  footer {{\n    text-align: center;\n    padding: 30px;\n    color: #aaa;\n    font-size: 0.82em;\n    border-top: 1px solid var(--border);\n  }}\n\n  /* ── Responsive ── */\n  @media (max-width: 768px) {{\n    .kpi-grid {{ grid-template-columns: 1fr 1fr; }}\n    .chart-row {{ grid-template-columns: 1fr; }}\n    .milestone-grid {{ grid-template-columns: 1fr; }}\n    .hero h1 {{ font-size: 1.6em; }}\n  }}\n</style>\n</head>\n<body>\n\n<!-- ═══════════ HERO ═══════════ -->\n<header class=\"hero\">\n  <h1>Nine Decades of Oscar-Winning Scores</h1>\n  <p class=\"subtitle\">A Historical Trend Analysis of the Academy Award for Best Original Score</p>\n  <p class=\"meta\">93 Ceremonies &middot; 1934–2026 &middot; {kpi_total_unique} Unique Composers</p>\n</header>\n\n<!-- ═══════════ KPI CARDS ═══════════ -->\n<div class=\"kpi-grid\">\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">{kpi_total_unique}</div>\n    <div class=\"kpi-label\">Total Unique Composers</div>\n    <div class=\"kpi-detail\">Across all 93 ceremonies</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">{kpi_max_wins}</div>\n    <div class=\"kpi-label\">Maximum Wins</div>\n    <div class=\"kpi-detail\">By a single composer</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">{kpi_repeat_rate}%</div>\n    <div class=\"kpi-label\">Repeat Winner Rate</div>\n    <div class=\"kpi-detail\">{repeat_years} of {len(rows)} ceremonies</div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">{kpi_best_decade}</div>\n    <div class=\"kpi-label\">Most Diverse Decade</div>\n    <div class=\"kpi-detail\">{kpi_best_decade_count} unique winners</div>\n  </div>\n</div>\n\n<div class=\"container\">\n\n<!-- ═══════════ SECTION 1: OVERVIEW ═══════════ -->\n<section id=\"overview\">\n  <h2>1. Dataset Overview &amp; Historical Context</h2>\n  <p class=\"lead\">\n    The Academy Award for Best Original Score has been awarded at 93 ceremonies spanning from the 6th Academy Awards\n    in 1934 through the 98th ceremony in March 2026. This dataset consolidates every winner into a single canonical record,\n    tracing the evolution of film music's highest honor across nine decades.\n  </p>\n  <p>\n    The award category has undergone several name changes and structural shifts across its history. In certain years, the Academy\n    split the category into separate awards for dramatic scores and comedy/musical scores; this dataset presents one\n    consolidated winner per ceremony year. The 93 winning scores represent <strong>{kpi_total_unique} distinct composers</strong>\n    (counting individuals within shared awards) and <strong>{len(set(r['film'] for r in rows))} unique films</strong>.\n  </p>\n  <p>\n    The composer pool reveals a striking concentration: <strong>{kpi_repeat_rate}%</strong> of all ceremonies were won by a composer\n    who had already claimed the award at least once before. A handful of names appear again and again across the decades,\n    while many composers appear just once — a testament to both the towering dominance of certain figures and the category's\n    capacity to recognize new voices.\n  </p>\n  <p>\n    The data spans from the Golden Age of Hollywood studio orchestras through the synthesizer experiments of the 1980s,\n    the orchestral renaissance of the 1990s and 2000s, and into today's eclectic landscape where traditional orchestral\n    writing coexists with electronic, experimental, and globally influenced scores.\n  </p>\n</section>\n\n<!-- ═══════════ SECTION 2: TOP COMPOSERS ═══════════ -->\n<section id=\"top-composers\">\n  <h2>2. Most Awarded Composers</h2>\n  <p>\n    A small cadre of composers has dominated the Best Original Score category. The top-ranked composer —\n    <strong>{top15[0][0]}</strong> — has won an extraordinary <strong>{top15[0][1]} times</strong>, a figure that\n    underscores a career of remarkable longevity and critical recognition. The table below ranks every composer who has\n    won more than once, along with the complete leaderboard chart.\n  </p>\n\n  <div class=\"chart-box\">\n    <canvas id=\"topComposersChart\" height=\"400\"></canvas>\n  </div>\n\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Rank</th>\n          <th>Composer</th>\n          <th>Wins</th>\n          <th>Winning Span</th>\n          <th>Era(s)</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\n# Build top composers table\nfor rank, (composer, wins) in enumerate(top_composers, 1):\n    years = sorted(composer_years[composer])\n    span = f\"{years[0]}–{years[-1]}\" if len(years) > 1 else str(years[0])\n    # Determine era tags\n    era_tags = []\n    for y in years:\n        if y <= 1959: t = \"Golden\"\n        elif y <= 1979: t = \"Silver\"\n        elif y <= 1999: t = \"Modern\"\n        else: t = \"Contemporary\"\n        if t not in era_tags:\n            era_tags.append(t)\n    era_html = \" \".join(\n        f'<span class=\"era-tag era-{t.lower()}\">{t}</span>'\n        for t in era_tags\n    )\n    row_class = \"highlight-row\" if rank <= 3 else \"\"\n    html += f\"\"\"        <tr class=\"{row_class}\">\n          <td class=\"num\"><strong>{rank}</strong></td>\n          <td><strong>{composer}</strong></td>\n          <td class=\"num\"><strong>{wins}</strong></td>\n          <td>{span}</td>\n          <td>{era_html}</td>\n        </tr>\n\"\"\"\n\nhtml += \"\"\"      </tbody>\n    </table>\n  </div>\n</section>\n\n<!-- ═══════════ SECTION 3: TEMPORAL PATTERNS ═══════════ -->\n<section id=\"temporal-patterns\">\n  <h2>3. Temporal Patterns &amp; Decade-by-Decade Breakdown</h2>\n  <p>\n    The distribution of awards across decades reveals distinct patterns of concentration and diversity.\n    Some decades were defined by a single dominant voice; others saw the award spread across a broad field\n    of composers, reflecting shifts in the industry, scoring technology, and Academy voting behavior.\n  </p>\n\n  <div class=\"chart-row\">\n    <div class=\"chart-box\">\n      <h3 style=\"margin-top:0\">Unique Winners per Decade</h3>\n      <canvas id=\"decadeUniqueChart\" height=\"280\"></canvas>\n    </div>\n    <div class=\"chart-box\">\n      <h3 style=\"margin-top:0\">Repeat vs. New Winners by Decade</h3>\n      <canvas id=\"decadeRepeatChart\" height=\"280\"></canvas>\n    </div>\n  </div>\n\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Decade</th>\n          <th>Ceremonies</th>\n          <th>Unique Winners</th>\n          <th>Repeat Winners</th>\n          <th>Top Composer</th>\n          <th>Concentration</th>\n        </tr>\n      </thead>\n      <tbody>\n\"\"\"\n\nfor d in decades_order:\n    ds = decade_stats.get(d)\n    if not ds or ds[\"ceremonies\"] == 0:\n        continue\n    concentration = round(ds[\"top_composer\"][1] / ds[\"ceremonies\"] * 100, 1) if ds[\"ceremonies\"] > 0 else 0\n    conc_label = f\"{concentration}%\" if concentration > 0 else \"—\"\n    html += f\"\"\"        <tr>\n          <td><strong>{d}</strong></td>\n          <td class=\"num\">{ds['ceremonies']}</td>\n          <td class=\"num\">{ds['unique_winners']}</td>\n          <td class=\"num\">{ds['repeat_winners']}</td>\n          <td>{ds['top_composer'][0]} ({ds['top_composer'][1]})</td>\n          <td class=\"num\">{conc_label}</td>\n        </tr>\n\"\"\"\n\nhtml += \"\"\"      </tbody>\n    </table>\n  </div>\n</section>\n\n<!-- ═══════════ SECTION 4: ERA ANALYSIS ═══════════ -->\n<section id=\"era-analysis\">\n  <h2>4. Era-Based Analysis of Winning Scores</h2>\n  <p>\n    Using approximate historical boundaries, the 93 ceremonies can be grouped into four major eras,\n    each defined by distinct industry conditions, scoring aesthetics, and composer profiles.\n  </p>\n\n  <div class=\"chart-box\">\n    <canvas id=\"eraChart\" height=\"350\"></canvas>\n  </div>\n\"\"\"\n\nfor era_name, stats in era_stats.items():\n    top3_str = \", \".join(f\"{c} ({w})\" for c, w in stats[\"top3\"])\n    html += f\"\"\"\n  <h3>{era_name}</h3>\n  <p>\n    <strong>{stats['ceremonies']} ceremonies</strong> &middot;\n    <strong>{stats['unique_composers']} unique composers</strong> &middot;\n    <strong>{stats['repeat_rate']}% repeat-winner rate</strong>\n  </p>\n  <p>\n    Defining composers: {top3_str}.\n  </p>\n\"\"\"\n\nhtml += \"\"\"\n</section>\n\n<!-- ═══════════ SECTION 5: MILESTONES ═══════════ -->\n<section id=\"notable-milestones\">\n  <h2>5. Notable Milestones &amp; Records</h2>\n\n  <div class=\"milestone-grid\">\n\"\"\"\n\n# First winner\nhtml += f\"\"\"\n    <div class=\"milestone\">\n      <div class=\"m-year\">First Winner &mdash; {first_winner['year']}</div>\n      <div class=\"m-title\">{first_winner['composer']}</div>\n      <p style=\"margin:4px 0 0;font-size:0.9em\">For <em>{first_winner['film']}</em></p>\n    </div>\n\"\"\"\n\n# Most recent winner\nhtml += f\"\"\"\n    <div class=\"milestone\">\n      <div class=\"m-year\">Most Recent Winner &mdash; {last_winner['year']}</div>\n      <div class=\"m-title\">{last_winner['composer']}</div>\n      <p style=\"margin:4px 0 0;font-size:0.9em\">For <em>{last_winner['film']}</em>, his fourth career win in the category</p>\n    </div>\n\"\"\"\n\n# Longest gap\nhtml += f\"\"\"\n    <div class=\"milestone\">\n      <div class=\"m-year\">Longest Gap Between Wins</div>\n      <div class=\"m-title\">{longest_gap_composer} &mdash; {longest_gap_years} Years</div>\n      <p style=\"margin:4px 0 0;font-size:0.9em\">{longest_gap_detail}</p>\n    </div>\n\"\"\"\n\n# Most wins\nhtml += f\"\"\"\n    <div class=\"milestone\">\n      <div class=\"m-year\">Most Wins by a Single Composer</div>\n      <div class=\"m-title\">{top15[0][0]} &mdash; {top15[0][1]} Wins</div>\n      <p style=\"margin:4px 0 0;font-size:0.9em\">Unmatched in Oscar scoring history</p>\n    </div>\n\"\"\"\n\n# Longest streak\nif streaks:\n    best_streak = max(streaks, key=lambda s: s[1])\n    html += f\"\"\"\n    <div class=\"milestone\">\n      <div class=\"m-year\">Longest Consecutive Win Streak</div>\n      <div class=\"m-title\">{best_streak[0]} &mdash; {best_streak[1]} Consecutive Years</div>\n      <p style=\"margin:4px 0 0;font-size:0.9em\">{best_streak[2]}–{best_streak[3]}</p>\n    </div>\n\"\"\"\n\n# First-time winner count\nhtml += f\"\"\"\n    <div class=\"milestone\">\n      <div class=\"m-year\">First-Time Winners</div>\n      <div class=\"m-title\">{kpi_total_unique} Composers Have Won</div>\n      <p style=\"margin:4px 0 0;font-size:0.9em\">Each representing a unique voice in film music</p>\n    </div>\n\"\"\"\n\nhtml += \"\"\"\n  </div>\n</section>\n\n<!-- ═══════════ SECTION 6: CONCLUSIONS ═══════════ -->\n<section id=\"conclusions\">\n  <h2>6. Key Takeaways &amp; Forward-Looking Observations</h2>\n\n  <h3>1. Concentration at the Top Is Persistent but Not Absolute</h3>\n  <p>\n\"\"\"\n\nhtml += f\"\"\"\n    With {top15[0][0]} holding <strong>{top15[0][1]} wins</strong> — more than double the next-highest composer —\n    the Best Original Score category has historically rewarded a small number of composers with extraordinary frequency.\n    Yet the data also shows that <strong>{kpi_total_unique} distinct composers</strong> have claimed the prize, meaning\n    the award has recognized far more individual voices than a casual observer might assume. The tension between repeat\n    dominance and new-voice discovery is a defining dynamic of the category's history.\n  </p>\n\n  <h3>2. The {kpi_best_decade} Stand Out as a Period of Maximum Diversity</h3>\n  <p>\n    The {kpi_best_decade} produced <strong>{kpi_best_decade_count} unique winners</strong> — the highest of any decade —\n    suggesting a period when the Academy spread its recognition across a wider field rather than concentrating it\n    on a few dominant figures.\n  </p>\n\n  <h3>3. Era Transitions Reflect Industry Disruption</h3>\n  <p>\n    The shift from the Golden Age studio system to the Silver Age brought new composers and new musical languages.\n    The Modern Era saw technology-driven experimentation alongside traditional orchestral work. The Contemporary Era,\n    from 2000 onward, is marked by an increasingly global and stylistically diverse pool, with winners spanning\n    electronic music, world music influences, and genre-blending approaches that would have been unthinkable\n    in the category's early decades.\n  </p>\n\n  <h3>4. The Composer as Brand</h3>\n  <p>\n    Composers like {top15[0][0]}, {top15[1][0] if len(top15) > 1 else 'Hans Zimmer'}, and {top15[2][0] if len(top15) > 2 else 'Maurice Jarre'}\n    have become brands in their own right — names that confer prestige on a film. The data shows that once a composer\n    enters the winner's circle, they are statistically more likely to return, suggesting that Academy voters develop\n    durable preferences for certain musical voices.\n  </p>\n\n  <h3>5. Looking Ahead: The Late 2020s and Beyond</h3>\n  <p>\n    The most recent data point — <strong>{last_winner['composer']}</strong> winning for <em>{last_winner['film']}</em> in {last_winner['year']} —\n    marks his fourth career Oscar, suggesting that a new era of repeat dominance may be emerging. The Contemporary Era\n    has seen an increasing number of composers with multiple wins, as well as a broadening of the stylistic range\n    recognized by the Academy. As film scoring continues to blend orchestral traditions with electronic, global,\n    and experimental approaches, the Best Original Score category is poised to reflect an ever more eclectic\n    musical landscape.\n  </p>\n</section>\n\n</div>\n\n<footer>\n  Report generated from the All Oscar Soundtracks dataset (1934–2026) &middot;\n  Source: Kaggle / ActarusLab &middot; Cross-referenced with AMPAS Official Database\n</footer>\n\n<!-- ═══════════ CHARTS ═══════════ -->\n<script>\n// ── Top Composers Bar Chart ──\nnew Chart(document.getElementById('topComposersChart'), {{\n  type: 'bar',\n  data: {{\n    labels: {js_json([c for c, _ in top15])},\n    datasets: [{{\n      label: 'Number of Wins',\n      data: {js_json([w for _, w in top15])},\n      backgroundColor: [\n        '#c9a84c', '#c9a84c', '#c9a84c',\n        '#7b8b9e', '#7b8b9e',\n        '#4a7c96', '#4a7c96', '#4a7c96',\n        '#2e8b6e', '#2e8b6e', '#2e8b6e', '#2e8b6e', '#2e8b6e',\n        '#888', '#888'\n      ],\n      borderColor: '#fff',\n      borderWidth: 1,\n      borderRadius: 3,\n    }}]\n  }},\n  options: {{\n    indexAxis: 'y',\n    responsive: true,\n    plugins: {{\n      legend: {{ display: false }},\n    }},\n    scales: {{\n      x: {{\n        title: {{ display: true, text: 'Number of Wins' }},\n        ticks: {{ stepSize: 1 }},\n        grid: {{ color: '#e8e4d8' }},\n      }},\n      y: {{\n        grid: {{ display: false }},\n      }},\n    }},\n  }},\n}});\n\n// ── Decade Unique Winners ──\nnew Chart(document.getElementById('decadeUniqueChart'), {{\n  type: 'bar',\n  data: {{\n    labels: {js_json(decade_chart_labels)},\n    datasets: [{{\n      label: 'Unique Winners',\n      data: {js_json(decade_chart_unique)},\n      backgroundColor: '#c9a84c',\n      borderRadius: 4,\n    }}],\n  }},\n  options: {{\n    responsive: true,\n    plugins: {{ legend: {{ display: false }} }},\n    scales: {{\n      y: {{\n        title: {{ display: true, text: 'Count' }},\n        beginAtZero: true,\n        ticks: {{ stepSize: 2 }},\n        grid: {{ color: '#e8e4d8' }},\n      }},\n      x: {{ grid: {{ display: false }} }},\n    }},\n  }},\n}});\n\n// ── Repeat vs New Winners by Decade ──\nnew Chart(document.getElementById('decadeRepeatChart'), {{\n  type: 'bar',\n  data: {{\n    labels: {js_json(decade_chart_labels)},\n    datasets: [\n      {{\n        label: 'Repeat Winners',\n        data: {js_json(decade_chart_repeat)},\n        backgroundColor: '#1a1a2e',\n        borderRadius: 4,\n      }},\n      {{\n        label: 'First-Time Winners',\n        data: {js_json([decade_chart_unique[i] - decade_chart_repeat[i] for i in range(len(decade_chart_unique))])},\n        backgroundColor: '#c9a84c',\n        borderRadius: 4,\n      }},\n    ],\n  }},\n  options: {{\n    responsive: true,\n    plugins: {{\n      legend: {{ position: 'bottom' }},\n    }},\n    scales: {{\n      x: {{ stacked: true, grid: {{ display: false }} }},\n      y: {{\n        stacked: true,\n        title: {{ display: true, text: 'Count' }},\n        ticks: {{ stepSize: 2 }},\n        grid: {{ color: '#e8e4d8' }},\n      }},\n    }},\n  }},\n}});\n\n// ── Era Comparison Chart ──\nnew Chart(document.getElementById('eraChart'), {{\n  type: 'bar',\n  data: {{\n    labels: {js_json(list(era_stats.keys()))},\n    datasets: [\n      {{\n        label: 'Total Ceremonies',\n        data: {js_json([s['ceremonies'] for s in era_stats.values()])},\n        backgroundColor: '#1a1a2e',\n        borderRadius: 4,\n      }},\n      {{\n        label: 'Unique Composers',\n        data: {js_json([s['unique_composers'] for s in era_stats.values()])},\n        backgroundColor: '#c9a84c',\n        borderRadius: 4,\n      }},\n    ],\n  }},\n  options: {{\n    responsive: true,\n    plugins: {{\n      legend: {{ position: 'bottom' }},\n    }},\n    scales: {{\n      y: {{\n        title: {{ display: true, text: 'Count' }},\n        beginAtZero: true,\n        grid: {{ color: '#e8e4d8' }},\n      }},\n      x: {{ grid: {{ display: false }} }},\n    }},\n  }},\n}});\n</script>\n\n</body>\n</html>\n\"\"\"\n\n# ── Write output ──────────────────────────────────────────────────────\nPath(\"/app/output\").mkdir(parents=True, exist_ok=True)\nwith open(\"/app/output/final_report.html\", \"w\", encoding=\"utf-8\") as f:\n    f.write(html)\n\nprint(\"Report saved to /app/output/final_report.html\")\nprint(f\"KPIs: {kpi_total_unique} composers, {kpi_max_wins} max wins, {kpi_repeat_rate}% repeat rate, best decade: {kpi_best_decade} ({kpi_best_decade_count})\")\n", "numLines": 905, "startLine": 1, "totalLines": 905}}

