    --contemp: #2e8b6e;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Georgia', 'Times New Roman', serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.7;
  }}

  /* ── Hero ── */
  .hero {{
    background: linear-gradient(135deg, #0d0d1a 0%, #1a1a2e 40%, #2d2d1a 100%);
    color: #f0e6c8;
    padding: 60px 40px 50px;
    text-align: center;
    border-bottom: 3px solid var(--accent);
  }}
  .hero h1 {{
    font-size: 2.6em;
    font-weight: normal;
    letter-spacing: 0.03em;
    margin-bottom: 10px;
    color: #f5e7c6;
  }}
  .hero .subtitle {{
    font-size: 1.15em;
    color: #c9a84c;
    font-style: italic;
    margin-bottom: 8px;
  }}
  .hero .meta {{
    font-size: 0.9em;
    color: #8a8a7a;
    margin-top: 15px;
  }}

  /* ── KPI Cards ── */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    max-width: 1100px;
    margin: -30px auto 40px;
    padding: 0 30px;
    position: relative;
    z-index: 2;
  }}
