"""

for d in decades_order:
    ds = decade_stats.get(d)
    if not ds or ds["ceremonies"] == 0:
        continue
    concentration = round(ds["top_composer"][1] / ds["ceremonies"] * 100, 1) if ds["ceremonies"] > 0 else 0
    conc_label = f"{concentration}%" if concentration > 0 else "—"
    html += f"""        <tr>
          <td><strong>{d}</strong></td>
          <td class="num">{ds['ceremonies']}</td>
          <td class="num">{ds['unique_winners']}</td>
